before:
 preview(){
  if(!this._path||this._hidden||this.data.busy||this._owner!==s.api.getSession()?.token)return;
  if(this.data.format==='PNG')wx.previewImage({current:this._path,urls:[this._path]});
  else wx.openDocument({filePath:this._path,fileType:'pdf',showMenu:false,fail:()=>{if(!this._disposed)this.setData({actionError:'当前客户端无法预览 PDF，请另存后使用本地阅读器打开。'});}});
 },
 saveLocal(){
  if(!this._path||this._hidden||this.data.busy||this._owner!==s.api.getSession()?.token)return;
  if(typeof wx.saveFileToDisk!=='function'){this.setData({actionError:'当前客户端不支持本地另存，请使用桌面微信或网页端。不自动分享到聊天。'});return;}
  const owner=this._owner;
  wx.saveFileToDisk({filePath:this._path,success:()=>{if(!this._disposed&&owner===s.api.getSession()?.token)this.setData({message:'已完成系统保存。'});},fail:e=>{if(!this._disposed&&!/cancel/.test(e.errMsg||''))this.setData({actionError:/开发者工具|not support|not supported|不支持.*调试/i.test(e.errMsg||'')?'开发者工具暂不支持系统另存，请用真机或桌面微信。临时文件尚未保存到系统目录。':'系统另存未完成，临时文件仍只在当前页面有效。'});}});
 }
});

after:
 fileCurrent(path,owner){
  // System preview/save can hide this page. Bind feedback to the file and login,
  // not the visibility epoch, so a legitimate system result can still return.
  return !this._disposed&&path===this._path&&owner===s.api.getSession()?.token;
 },
 preview(){
  if(!this._path||this._hidden||this.data.busy||this._disposed||this._owner!==s.api.getSession()?.token)return;
  const path=this._path,owner=this._owner,format=this.data.format;
  this.setData({actionError:''});
  const fail=e=>{if(this.fileCurrent(path,owner)&&!/cancel/i.test(e?.errMsg||''))this.setData({actionError:format==='PNG'?'图片预览失败，请重试或保存到本机查看。':'当前客户端无法预览 PDF，请另存后使用本地阅读器打开。'});};
  try{
   if(format==='PNG')wx.previewImage({current:path,urls:[path],fail});
   else wx.openDocument({filePath:path,fileType:'pdf',showMenu:false,fail});
  }catch(e){fail(e);}
 },
 saveLocal(){
  if(!this._path||this._hidden||this.data.busy||this._disposed||this._owner!==s.api.getSession()?.token)return;
  if(typeof wx.saveFileToDisk!=='function'){this.setData({actionError:'当前客户端不支持本地另存，请使用桌面微信或网页端。不自动分享到聊天。'});return;}
  const path=this._path,owner=this._owner;
  this.setData({actionError:'',message:''});
  const fail=e=>{if(this.fileCurrent(path,owner)&&!/cancel/i.test(e?.errMsg||''))this.setData({actionError:/开发者工具|not support|not supported|不支持.*调试/i.test(e?.errMsg||'')?'开发者工具暂不支持系统另存，请用真机或桌面微信。临时文件尚未保存到系统目录。':'系统另存未完成，临时文件仍只在当前页面有效。'});};
  try{wx.saveFileToDisk({filePath:path,success:()=>{if(this.fileCurrent(path,owner))this.setData({message:'已完成系统保存。'});},fail});}catch(e){fail(e);}
 }
});
